Here is a complete, self-contained implementation of an LRU Cache in Rust.

It uses `std::collections::HashMap` for O(1) lookups and a custom **Doubly Linked List** (using `Rc` and `RefCell`) to manage the order of keys in O(1) time.

### The Implementation

```rust
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

// 1. Define the Node structure
// We use Rc<RefCell<>> to allow shared ownership and interior mutability
// required for a doubly linked list where nodes point to each other.
type NodeRef<K, V> = Rc<RefCell<Node<K, V>>>;

struct Node<K, V> {
    key: K,
    value: V,
    prev: Option<NodeRef<K, V>>,
    next: Option<NodeRef<K, V>>,
}

impl<K, V> Node<K, V> {
    fn new(key: K, value: V) -> NodeRef<K, V> {
        Rc::new(RefCell::new(Node {
            key,
            value,
            prev: None,
            next: None,
        }))
    }
}

// 2. Define the LRU Cache structure
pub struct LruCache<K, V> {
    capacity: usize,
    map: HashMap<K, NodeRef<K, V>>,
    // We use Option<NodeRef> for head and tail to handle the empty state easily
    head: Option<NodeRef<K, V>>, // Most Recently Used (MRU)
    tail: Option<NodeRef<K, V>>, // Least Recently Used (LRU)
}

impl<K: std::hash::Hash + Eq + Clone, V: Clone> LruCache<K, V> {
    pub fn new(capacity: usize) -> Self {
        LruCache {
            capacity,
            map: HashMap::with_capacity(capacity),
            head: None,
            tail: None,
        }
    }

    // O(1) Get
    pub fn get(&mut self, key: &K) -> Option<V> {
        if let Some(node) = self.map.get(key).cloned() {
            // Move the accessed node to the head (MRU position)
            self.move_to_head(node.clone());
            // Return a clone of the value
            Some(node.borrow().value.clone())
        } else {
            None
        }
    }

